    }

    ///<summary>End a pause now. The active block, if any, is applied at once.</summary>
    public void Resume(ChronosResumeParameters data)
    {
        _haContext.CallService("chronos", "resume", null, data);
    }

    ///<summary>End a pause now. The active block, if any, is applied at once.</summary>
    ///<param name="scheduleId">Schedule id, alternative to the name eg: abc12345</param>
    ///<param name="name">Exact schedule name, case-insensitive (alternative to the id) eg: Garden irrigation</param>
