    {
        _haContext.CallService("chronos", "resume", null, new ChronosResumeParameters { ScheduleId = scheduleId, Name = name });
    }

    ///<summary>Enable or disable a Chronos schedule. Meant to be called from HA automations: schedules are not exposed as entities, this service is the equivalent of the toggle in the card. Target by schedule id or by name (the name must be unique; on a tie the service does nothing and logs a warning). </summary>
